window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-97ef3205b4db18da"]={"versions": [{"id": "FIG-97ef3205b4db18da", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition der ECU-Konfigurationsparameter (ECUC-Metamodell-Ausschnitt) für das BSW-Modul Crypto Service Manager (CSM) in der AUTOSAR Classic Platform. Das Diagramm spezifiziert die strukturelle Zuordnung von periodischen CSM-Hauptfunktionen (<code>MainFunction</code>) zu Multicore- bzw. OS-Partitionen (<code>EcucPartition</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm modelliert folgende Konfigurationselemente und deren Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><strong><code>Csm</code></strong> (<code>EcucModuleDef</code>): Wurzelmoduldefinition mit Multiplizität 0..1.</li>\n<li><strong><code>CsmMainFunction</code></strong> (<code>EcucParamConfContainerDef</code>): Untercontainer von <code>Csm</code> via Kompositionsbeziehung <code>+container</code> (Multiplizität 0..\\*).</li>\n<li><strong><code>CsmMainFunctionPeriod</code></strong> (<code>EcucFloatParamDef</code>): Konfigurationsparameter von <code>CsmMainFunction</code> via Komposition <code>+parameter</code> (Multiplizität 0..1, Wertebereich <code>min = 0</code>, <code>max = INF</code>).</li>\n<li><strong><code>CsmMainFunctionPartitionRef</code></strong> (<code>EcucReferenceDef</code>): Referenzdefinition innerhalb von <code>CsmMainFunction</code> via Komposition <code>+reference</code> (Multiplizität 1..1).</li>\n<li><strong><code>EcucPartition</code></strong> (<code>EcucParamConfContainerDef</code>): Zielcontainer der Referenz <code>CsmMainFunctionPartitionRef</code> via gerichtete Assoziation <code>+destination</code> (Multiplizität 0..\\*).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmetamodell ohne dynamische Sequenzabläufe. Die Konfiguration definiert die Rahmenbedingungen für die spätere Ablaufsteuerung durch das BSW Scheduler (SchM) bzw. Betriebssystem (OS): Jede Instanz von <code>CsmMainFunction</code> wird genau einer Zielpartition (<code>EcucPartition</code>) zugeordnet und kann optional eine Aufrufperiode (<code>CsmMainFunctionPeriod</code>) in Sekunden deklarieren, um die zyklische Abarbeitung im Multicore-/Mehrpartitionskontext zu steuern.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Konfigurationsvorgabe für die Parametrierung des CSM-Moduls:</p>\n<ul class=\"fig-list\">\n<li>Jede instanziierte <code>CsmMainFunction</code> erfordert zwingend eine gültige Zuweisung zu einer OS-Partition (<code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code> für <code>CsmMainFunctionPartitionRef</code>).</li>\n<li>Die Zykluszeit <code>CsmMainFunctionPeriod</code> ist optional (0..1) und auf nicht-negative Gleitkommawerte beschränkt (<code>min = 0</code>, <code>max = INF</code>).</li>\n<li>Generatoren für den BSW-Scheduler und die RTE müssen anhand dieser Einträge partitions- und funktionsspezifische Task-Zuweisungen und Schedule-Aufrufe (<code>Csm_MainFunction_&lt;Partition&gt;</code>) erzeugen.</li>\n</ul>"}, {"id": "FIG-382579af20eac952", "releases": ["R22-11", "EXTERN"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Definition der ECU-Konfigurationsparameter (ECUC-Metamodell-Ausschnitt) für das BSW-Modul Crypto Service Manager (CSM) in der AUTOSAR Classic Platform. Das Diagramm spezifiziert die strukturelle Zuordnung von periodischen CSM-Hauptfunktionen (<code>MainFunction</code>) zu Multicore- bzw. OS-Partitionen (<code>EcucPartition</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm modelliert folgende Konfigurationselemente und deren Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><strong><code>Csm</code></strong> (<code>EcucModuleDef</code>): Wurzelmoduldefinition mit Multiplizität 0..1.</li>\n<li><strong><code>CsmMainFunction</code></strong> (<code>EcucParamConfContainerDef</code>): Untercontainer von <code>Csm</code> via Kompositionsbeziehung <code>+container</code> (Multiplizität 0..\\*).</li>\n<li><strong><code>CsmMainFunctionPeriod</code></strong> (<code>EcucFloatParamDef</code>): Konfigurationsparameter von <code>CsmMainFunction</code> via Komposition <code>+parameter</code> (Multiplizität 0..1, Wertebereich <code>min = 0</code>, <code>max = INF</code>).</li>\n<li><strong><code>CsmMainFunctionPartitionRef</code></strong> (<code>EcucReferenceDef</code>): Referenzdefinition innerhalb von <code>CsmMainFunction</code> via Komposition <code>+reference</code> (Multiplizität 1..1).</li>\n<li><strong><code>EcucPartition</code></strong> (<code>EcucParamConfContainerDef</code>): Zielcontainer der Referenz <code>CsmMainFunctionPartitionRef</code> via gerichtete Assoziation <code>+destination</code> (Multiplizität 0..\\*).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurationsmetamodell ohne dynamische Sequenzabläufe. Die Konfiguration definiert die Rahmenbedingungen für die spätere Ablaufsteuerung durch das BSW Scheduler (SchM) bzw. Betriebssystem (OS): Jede Instanz von <code>CsmMainFunction</code> wird genau einer Zielpartition (<code>EcucPartition</code>) zugeordnet und kann optional eine Aufrufperiode (<code>CsmMainFunctionPeriod</code>) in Sekunden deklarieren, um die zyklische Abarbeitung im Multicore-/Mehrpartitionskontext zu steuern.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Konfigurationsvorgabe für die Parametrierung des CSM-Moduls:</p>\n<ul class=\"fig-list\">\n<li>Jede instanziierte <code>CsmMainFunction</code> erfordert zwingend eine gültige Zuweisung zu einer OS-Partition (<code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 1</code> für <code>CsmMainFunctionPartitionRef</code>).</li>\n<li>Die Zykluszeit <code>CsmMainFunctionPeriod</code> ist optional (0..1) und auf nicht-negative Gleitkommawerte beschränkt (<code>min = 0</code>, <code>max = INF</code>).</li>\n<li>Generatoren für den BSW-Scheduler und die RTE müssen anhand dieser Einträge partitions- und funktionsspezifische Task-Zuweisungen und Schedule-Aufrufe (<code>Csm_MainFunction_&lt;Partition&gt;</code>) erzeugen.</li>\n</ul>"}], "trans": [{"from": "FIG-97ef3205b4db18da", "to": "FIG-382579af20eac952", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
